function populateCountryDropdown() {
  const sel = document.getElementById('mapCountrySelect');
  if (!sel) return;
  const sorted = Object.keys(SUPERSTORE_COUNTRIES).sort();
  const markets = {};
  sorted.forEach(c => {
    const m = SUPERSTORE_COUNTRIES[c].market || 'Other';
    if (!markets[m]) markets[m] = [];
    markets[m].push(c);
  });
  
  let html = '<option value="">-- Choose Country (147)... --</option>';
  Object.keys(markets).sort().forEach(m => {
    html += `<optgroup label="Market: ${m}">`;
    markets[m].forEach(c => {
      const info = SUPERSTORE_COUNTRIES[c];
      html += `<option value="${esc(c)}">${esc(c)} (${info.region})</option>`;
    });
    html += `</optgroup>`;
  });
  
  sel.innerHTML = html;
  if (state.map.selectedCountry) {
    sel.value = state.map.selectedCountry;
  }
}

async function initWorldMap() {
  const wrap = document.getElementById('mapSvgWrap');
  const loading = document.getElementById('mapSvgLoading');
  if (!wrap) return;

  if (state.map.svgLoaded) {
    updateMapHighlighting();
    return;
  }

  try {
    let res = await fetch('/assets/world-map.svg');
    if (!res.ok) res = await fetch('assets/world-map.svg');
    if (!res.ok) res = await fetch('frontend/assets/world-map.svg');
    if (!res.ok) res = await fetch('../assets/world-map.svg');
    if (!res.ok) throw new Error('Could not load world-map.svg');
    const svgText = await res.text();
    wrap.innerHTML = svgText;
    state.map.svgLoaded = true;
    if (loading) loading.style.display = 'none';

    setupMapInteractions();
    updateMapHighlighting();
  } catch (err) {
    console.error('Failed to load map SVG:', err);
    if (loading) {
      loading.innerHTML = `<div style="color:var(--accent-red);font-size:12px;padding:12px;">Failed to load map asset.</div>`;
    }
  }
}

function setupMapInteractions() {
  const container = document.getElementById('geoMapContainer');
  const wrap = document.getElementById('mapSvgWrap');
  const svg = wrap ? wrap.querySelector('svg') : null;
  const tooltip = document.getElementById('mapTooltip');
  if (!svg || !container) return;

  state.map.viewBox = { x: 0, y: 0, w: 1010, h: 666 };
  applyViewBox();

  // Pointer move tooltip
  svg.addEventListener('mousemove', (e) => {
    const target = e.target.closest('.map-country');
    if (!target) {
      if (tooltip) tooltip.style.display = 'none';
      return;
    }
    const countryName = target.getAttribute('data-country');
    if (!countryName) {
      if (tooltip) tooltip.style.display = 'none';
      return;
    }

    const info = SUPERSTORE_COUNTRIES[countryName];
    if (tooltip) {
      tooltip.style.display = 'block';
      const rect = container.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      let html = `<div style="font-weight:700;font-size:12px;color:var(--text-primary);">${esc(countryName)}</div>`;
      if (info) {
        html += `<div style="color:var(--accent-blue);font-size:11px;margin-top:2px;">${info.market} &middot; ${info.region}</div>`;
        html += `<div style="color:var(--text-secondary);font-size:11px;margin-top:2px;">${fmtNum(info.orders)} catalog orders</div>`;
        html += `<div style="color:var(--accent-cyan);font-size:10px;margin-top:4px;"><i class="fa-solid fa-arrow-pointer"></i> Click to inspect</div>`;
      } else {
        html += `<div style="color:var(--text-muted);font-size:11px;margin-top:2px;">No store presence in catalog</div>`;
      }
      tooltip.innerHTML = html;

      const tipWidth = tooltip.offsetWidth || 160;
      const tipHeight = tooltip.offsetHeight || 60;
      let left = x;
      let top = y - 10;
      if (left - tipWidth / 2 < 10) left = tipWidth / 2 + 10;
      if (left + tipWidth / 2 > rect.width - 10) left = rect.width - tipWidth / 2 - 10;
      if (top - tipHeight < 10) top = y + 25;

      tooltip.style.left = left + 'px';
      tooltip.style.top = top + 'px';
    }
  });

  svg.addEventListener('mouseleave', () => {
    if (tooltip) tooltip.style.display = 'none';
  });

  // Country click
  svg.addEventListener('click', (e) => {
    const target = e.target.closest('.map-country.has-data');
    if (!target) return;
    const countryName = target.getAttribute('data-country');
    if (countryName && SUPERSTORE_COUNTRIES[countryName]) {
      selectCountry(countryName);
    }
  });

  // Keyboard navigation on paths
  svg.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      const target = e.target.closest('.map-country.has-data');
      if (target) {
        e.preventDefault();
        const countryName = target.getAttribute('data-country');
        if (countryName && SUPERSTORE_COUNTRIES[countryName]) {
          selectCountry(countryName);
        }
      }
    }
  });

  // Drag to pan
  let isDown = false;
  let startX = 0, startY = 0;
  let origX = 0, origY = 0;

  container.addEventListener('mousedown', (e) => {
    if (e.button !== 0) return;
    isDown = true;
    container.classList.add('grabbing');
    startX = e.clientX;
    startY = e.clientY;
    origX = state.map.viewBox.x;
    origY = state.map.viewBox.y;
  });

  window.addEventListener('mousemove', (e) => {
    if (!isDown) return;
    const dx = e.clientX - startX;
    const dy = e.clientY - startY;
    const factor = state.map.viewBox.w / container.clientWidth;
    state.map.viewBox.x = origX - dx * factor;
    state.map.viewBox.y = origY - dy * factor;
    applyViewBox();
  });

  window.addEventListener('mouseup', () => {
    if (isDown) {
      isDown = false;
      container.classList.remove('grabbing');
    }
  });

  // Touch to pan for mobile
  let touchStartX = 0, touchStartY = 0;
  let touchOrigX = 0, touchOrigY = 0;
  let isTouchPanning = false;

  container.addEventListener('touchstart', (e) => {
    if (e.touches.length === 1) {
      isTouchPanning = true;
      touchStartX = e.touches[0].clientX;
      touchStartY = e.touches[0].clientY;
      touchOrigX = state.map.viewBox.x;
      touchOrigY = state.map.viewBox.y;
    }
  }, { passive: true });

  container.addEventListener('touchmove', (e) => {
    if (!isTouchPanning || e.touches.length !== 1) return;
    const dx = e.touches[0].clientX - touchStartX;
    const dy = e.touches[0].clientY - touchStartY;
    const factor = state.map.viewBox.w / (container.clientWidth || 1);
    state.map.viewBox.x = touchOrigX - dx * factor;
    state.map.viewBox.y = touchOrigY - dy * factor;
    applyViewBox();
  }, { passive: true });

  container.addEventListener('touchend', () => {
    isTouchPanning = false;
  });

  // Mouse wheel zoom
  container.addEventListener('wheel', (e) => {
    e.preventDefault();
    const factor = e.deltaY > 0 ? 1.15 : 0.85;
    zoomMap(1 / factor);
  }, { passive: false });
}

function applyViewBox() {
  const wrap = document.getElementById('mapSvgWrap');
  const svg = wrap ? wrap.querySelector('svg') : null;
  if (!svg) return;
  const vb = state.map.viewBox;
  svg.setAttribute('viewBox', `${vb.x} ${vb.y} ${vb.w} ${vb.h}`);
}

function zoomMap(scaleFactor) {
  const vb = state.map.viewBox;
  const newW = Math.max(150, Math.min(1010, vb.w / scaleFactor));
  const newH = Math.max(100, Math.min(666, vb.h / scaleFactor));
  const cx = vb.x + vb.w / 2;
  const cy = vb.y + vb.h / 2;
  vb.x = cx - newW / 2;
  vb.y = cy - newH / 2;
  vb.w = newW;
  vb.h = newH;
  applyViewBox();
}

function resetMapZoom() {
  state.map.viewBox = { x: 0, y: 0, w: 1010, h: 666 };
  applyViewBox();
}

function handleCountryDropdownChange(val) {
  if (!val) {
    clearCountrySelection();
  } else {
    selectCountry(val);
  }
}

async function selectCountry(countryName) {
  if (!countryName || !SUPERSTORE_COUNTRIES[countryName]) {
    clearCountrySelection();
    return;
  }

  state.map.selectedCountry = countryName;

  const sel = document.getElementById('mapCountrySelect');
  if (sel && sel.value !== countryName) sel.value = countryName;

  const wrap = document.getElementById('mapSvgWrap');
  if (wrap) {
    wrap.querySelectorAll('.map-country').forEach(el => el.classList.remove('selected'));
    const safeCountry = (window.CSS && CSS.escape ? CSS.escape(countryName) : countryName.replace(/["\\]/g, '\\$&'));
    const matched = wrap.querySelectorAll(`.map-country[data-country="${safeCountry}"]`);
    matched.forEach(el => el.classList.add('selected'));
  }

  if (state.map.countryCache[countryName]) {
    state.map.loading = false;
    state.map.error = null;
    updateLocationStats();
    return;
  }

  state.map.loading = true;
  state.map.error = null;
  updateLocationStats();

  const reqId = ++state.map.activeRequestId;

  try {
    const rows = await fetchAllCountryOrders(countryName, reqId);
    if (reqId !== state.map.activeRequestId) return;

    state.map.countryCache[countryName] = rows;
    state.map.loading = false;
    updateLocationStats();
  } catch (err) {
    if (reqId !== state.map.activeRequestId) return;
    console.error(`Failed to fetch orders for ${countryName}:`, err);
    state.map.loading = false;
    state.map.error = err.message || 'Failed to load order data';
    updateLocationStats();
  }
}

async function fetchAllCountryOrders(countryName, reqId) {
  const initialLimit = 10000;
  const url = `${API_BASE_URL}/api/orders?q=${encodeURIComponent(countryName)}&limit=${initialLimit}&page=1`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const json = await res.json();

  let rows = (json.data || []).filter(r => r.country === countryName);

  if (json.total > initialLimit && (json.data || []).length < json.total) {
    let page = 2;
    const totalPages = Math.ceil(json.total / initialLimit);
    while (page <= totalPages) {
      if (reqId !== state.map.activeRequestId) return [];
      const nextUrl = `${API_BASE_URL}/api/orders?q=${encodeURIComponent(countryName)}&limit=${initialLimit}&page=${page}`;
      const nextRes = await fetch(nextUrl);
      if (!nextRes.ok) break;
      const nextJson = await nextRes.json();
      const nextMatching = (nextJson.data || []).filter(r => r.country === countryName);
      rows = rows.concat(nextMatching);
      page++;
    }
  }
  return rows;
}

function retryCountryFetch() {
  if (state.map.selectedCountry) {
    const c = state.map.selectedCountry;
    delete state.map.countryCache[c];
    selectCountry(c);
  }
}

function clearCountrySelection() {
  state.map.selectedCountry = null;
  state.map.error = null;
  state.map.loading = false;

  const sel = document.getElementById('mapCountrySelect');
  if (sel) sel.value = '';

  const wrap = document.getElementById('mapSvgWrap');
  if (wrap) {
    wrap.querySelectorAll('.map-country').forEach(el => el.classList.remove('selected'));
  }

  updateLocationStats();
}

function setLocDateMode(mode) {
  state.map.dateMode = mode;
  updateLocationStats();
}

function handleLocDateChange() {
  if (state.map.dateMode === 'range') {
    const s = document.getElementById('locStartDate');
    const e = document.getElementById('locEndDate');
    if (s && e) {
      state.map.startDate = s.value;
      state.map.endDate = e.value;
    }
  } else {
    const d = document.getElementById('locSingleDate');
    if (d) {
      state.map.singleDate = d.value;
    }
  }
  updateLocationStats();
}

function setLocDatePreset(preset) {
  state.map.dateMode = 'range';
  if (preset === 'all') {
    state.map.startDate = '2011-01-01';
    state.map.endDate = '2014-12-31';
  } else if (preset === '2014') {
    state.map.startDate = '2014-01-01';
    state.map.endDate = '2014-12-31';
  } else if (preset === '2013') {
    state.map.startDate = '2013-01-01';
    state.map.endDate = '2013-12-31';
  } else if (preset === 'q4_2014') {
    state.map.startDate = '2014-10-01';
    state.map.endDate = '2014-12-31';
  }
  updateLocationStats();
}

function stepSingleDay(deltaDays) {
  state.map.dateMode = 'single';
  const parts = (state.map.singleDate || '2014-12-30').split('-');
  const y = parseInt(parts[0], 10);
  const m = parseInt(parts[1], 10) - 1;
  const d = parseInt(parts[2], 10);
  const dt = new Date(Date.UTC(y, m, d + deltaDays));

  const minD = new Date(Date.UTC(2011, 0, 1));
  const maxD = new Date(Date.UTC(2014, 11, 31));
  let target = dt;
  if (target < minD) target = minD;
  if (target > maxD) target = maxD;

  state.map.singleDate = target.toISOString().substring(0, 10);
  updateLocationStats();
}

function setSingleDayPreset(dateStr) {
  state.map.dateMode = 'single';
  state.map.singleDate = dateStr;
  updateLocationStats();
}

function updateMapHighlighting() {
  const wrap = document.getElementById('mapSvgWrap');
  if (!wrap) return;
  const f = state.dashboardFilters || {};
  const activeRegion = f.region || '';
  const activeMarket = f.market || '';
  const hasFilter = !!(activeRegion || activeMarket);

  wrap.querySelectorAll('.map-country').forEach(el => {
    el.classList.remove('filter-matched', 'filter-dimmed');
    const countryName = el.getAttribute('data-country');
    const meta = SUPERSTORE_COUNTRIES[countryName];
    if (!meta) return;

    if (hasFilter) {
      const matchRegion = !activeRegion || meta.region === activeRegion;
      const matchMarket = !activeMarket || meta.market === activeMarket;
      if (matchRegion && matchMarket) {
        el.classList.add('filter-matched');
      } else {
        el.classList.add('filter-dimmed');
      }
    }
  });
}

function renderLocationStatsHeader(country, meta) {
  return `
    <div class="loc-card-header">
      <div class="loc-title-wrap">
        <div class="loc-flag-icon"><i class="fa-solid fa-location-dot"></i></div>
        <div>
          <div class="loc-country-title">${esc(country)}</div>
          <div class="loc-country-badges">
            <span class="badge badge-info">${esc(meta.region)}</span>
            <span class="badge badge-purple">${esc(meta.market)}</span>
          </div>
        </div>
      </div>
      <button class="filter-reset-btn" style="padding:4px 10px;font-size:11px;" onclick="clearCountrySelection()" title="Clear country selection">
        <i class="fa-solid fa-xmark"></i> Clear
      </button>
    </div>
  `;
}

function renderLocationDateSection() {
  const isRange = state.map.dateMode === 'range';
  return `
    <div class="loc-date-section">
      <div class="loc-date-mode-toggle">
        <button class="loc-mode-btn ${isRange ? 'active' : ''}" onclick="setLocDateMode('range')">
          <i class="fa-regular fa-calendar-days"></i> Date Range
        </button>
        <button class="loc-mode-btn ${!isRange ? 'active' : ''}" onclick="setLocDateMode('single')">
          <i class="fa-regular fa-calendar"></i> Single Day
        </button>
      </div>

      ${isRange ? `
        <div class="loc-date-inputs">
          <div class="loc-date-group">
            <label class="filter-label" style="font-size:11px;">From</label>
            <input type="date" class="loc-date-input" id="locStartDate" value="${state.map.startDate}" min="2011-01-01" max="2014-12-31" onchange="handleLocDateChange()">
          </div>
          <div class="loc-date-group">
            <label class="filter-label" style="font-size:11px;">To</label>
            <input type="date" class="loc-date-input" id="locEndDate" value="${state.map.endDate}" min="2011-01-01" max="2014-12-31" onchange="handleLocDateChange()">
          </div>
        </div>
        <div class="loc-quick-dates">
          <span style="font-size:10px;color:var(--text-muted);margin-right:2px;">Presets:</span>
          <button class="loc-quick-btn" onclick="setLocDatePreset('all')">All Time</button>
          <button class="loc-quick-btn" onclick="setLocDatePreset('2014')">2014</button>
          <button class="loc-quick-btn" onclick="setLocDatePreset('2013')">2013</button>
          <button class="loc-quick-btn" onclick="setLocDatePreset('q4_2014')">Q4 2014</button>
        </div>
      ` : `
        <div class="loc-single-date-wrap">
          <button class="loc-nav-btn" onclick="stepSingleDay(-1)" title="Previous day"><i class="fa-solid fa-chevron-left"></i></button>
          <input type="date" class="loc-date-input" id="locSingleDate" value="${state.map.singleDate}" min="2011-01-01" max="2014-12-31" onchange="handleLocDateChange()">
          <button class="loc-nav-btn" onclick="stepSingleDay(1)" title="Next day"><i class="fa-solid fa-chevron-right"></i></button>
        </div>
        <div class="loc-quick-dates">
          <span style="font-size:10px;color:var(--text-muted);margin-right:2px;">Sample Days:</span>
          <button class="loc-quick-btn" onclick="setSingleDayPreset('2014-12-30')">Dec 30, 2014</button>
          <button class="loc-quick-btn" onclick="setSingleDayPreset('2014-11-28')">Nov 28, 2014</button>
          <button class="loc-quick-btn" onclick="setSingleDayPreset('2014-06-18')">Jun 18, 2014</button>
        </div>
      `}
    </div>
  `;
}

function updateLocationStats() {
  const container = document.getElementById('geoStatsCard');
  if (!container) return;

  const country = state.map.selectedCountry;

  // 1. Default State: No country selected
  if (!country) {
    container.innerHTML = `
      <div class="loc-empty-state">
        <div class="loc-empty-icon"><i class="fa-solid fa-earth-americas"></i></div>
        <div class="loc-empty-title">Country Performance Deep-Dive</div>
        <div class="loc-empty-desc">
          Select any highlighted country on the map or choose from the dropdown above to inspect localized sales, profit, orders, and shipping breakdowns.
        </div>
        <div class="loc-popular-title">Quick Picks:</div>
        <div class="loc-quick-picks">
          <button class="loc-chip" onclick="selectCountry('United States')">ðŸ‡ºðŸ‡¸ United States</button>
          <button class="loc-chip" onclick="selectCountry('Australia')">ðŸ‡¦ðŸ‡º Australia</button>
          <button class="loc-chip" onclick="selectCountry('France')">ðŸ‡«ðŸ‡· France</button>
          <button class="loc-chip" onclick="selectCountry('Germany')">ðŸ‡©ðŸ‡ª Germany</button>
          <button class="loc-chip" onclick="selectCountry('United Kingdom')">ðŸ‡¬ðŸ‡§ United Kingdom</button>
          <button class="loc-chip" onclick="selectCountry('China')">ðŸ‡¨ðŸ‡³ China</button>
          <button class="loc-chip" onclick="selectCountry('Brazil')">ðŸ‡§ðŸ‡· Brazil</button>
          <button class="loc-chip" onclick="selectCountry('Indonesia')">ðŸ‡®ðŸ‡© Indonesia</button>
        </div>
      </div>
    `;
    return;
  }

  const meta = SUPERSTORE_COUNTRIES[country] || { region: 'Unknown', market: 'Unknown', orders: 0 };
  let headerHtml = renderLocationStatsHeader(country, meta);
  let dateHtml = renderLocationDateSection();

  // 2. Loading State
  if (state.map.loading) {
    container.innerHTML = `
      ${headerHtml}
      ${dateHtml}
      <div class="loc-loading-state">
        <div class="dashboard-loading-spinner" style="width:32px;height:32px;margin-bottom:12px;"></div>
        <div style="font-weight:600;font-size:13px;color:var(--text-primary);">Loading complete order records for ${esc(country)}...</div>
        <div style="font-size:11px;color:var(--text-secondary);margin-top:4px;">Retrieving dataset to reconcile sales, profit &amp; shipping measures</div>
      </div>
    `;
    return;
  }

  // 3. Error State
  if (state.map.error) {
    container.innerHTML = `
      ${headerHtml}
      ${dateHtml}
      <div class="loc-error-state">
        <i class="fa-solid fa-circle-exclamation" style="font-size:26px;color:var(--accent-red);margin-bottom:8px;"></i>
        <div style="font-weight:600;color:var(--accent-red);font-size:14px;">Failed to load order data</div>
        <div style="font-size:12px;color:var(--text-secondary);margin:6px 0 12px;">${esc(state.map.error)}</div>
        <button class="filter-apply-btn" onclick="retryCountryFetch()"><i class="fa-solid fa-rotate-right"></i> Retry Fetch</button>
      </div>
    `;
    return;
  }

  // 4. Invalid Date Range State
  const isRange = state.map.dateMode === 'range';
  if (isRange) {
    if (!state.map.startDate || !state.map.endDate || state.map.startDate > state.map.endDate) {
      const msg = (!state.map.startDate || !state.map.endDate)
        ? 'Please provide both valid start and end dates.'
        : `Invalid date range: Start date (${state.map.startDate}) is after End date (${state.map.endDate}).`;
      container.innerHTML = `
        ${headerHtml}
        ${dateHtml}
        <div class="loc-alert error">
          <i class="fa-solid fa-triangle-exclamation"></i>
          <span>${esc(msg)}</span>
        </div>
        <div class="loc-kpi-grid">
          <div class="loc-kpi-item"><div class="loc-kpi-label">Sales</div><div class="loc-kpi-val">&mdash;</div></div>
          <div class="loc-kpi-item"><div class="loc-kpi-label">Profit</div><div class="loc-kpi-val">&mdash;</div></div>
          <div class="loc-kpi-item"><div class="loc-kpi-label">Orders</div><div class="loc-kpi-val">&mdash;</div></div>
          <div class="loc-kpi-item"><div class="loc-kpi-label">Shipping Cost</div><div class="loc-kpi-val">&mdash;</div></div>
        </div>
      `;
      return;
    }
  } else {
    if (!state.map.singleDate) {
      container.innerHTML = `
        ${headerHtml}
        ${dateHtml}
        <div class="loc-alert error">
          <i class="fa-solid fa-triangle-exclamation"></i>
          <span>Please select a valid date.</span>
        </div>
        <div class="loc-kpi-grid">
          <div class="loc-kpi-item"><div class="loc-kpi-label">Sales</div><div class="loc-kpi-val">&mdash;</div></div>
          <div class="loc-kpi-item"><div class="loc-kpi-label">Profit</div><div class="loc-kpi-val">&mdash;</div></div>
          <div class="loc-kpi-item"><div class="loc-kpi-label">Orders</div><div class="loc-kpi-val">&mdash;</div></div>
          <div class="loc-kpi-item"><div class="loc-kpi-label">Shipping Cost</div><div class="loc-kpi-val">&mdash;</div></div>
        </div>
      `;
      return;
    }
  }

  // 5. Filter Records for Country and Date
  const allRows = state.map.countryCache[country] || [];
  let filteredRows = [];
  let dateContextLabel = '';

  if (!isRange) {
    const day = state.map.singleDate;
    filteredRows = allRows.filter(r => r.order_date && r.order_date.startsWith(day));
    dateContextLabel = `Single Day: ${day}`;
  } else {
    const s = state.map.startDate;
    const e = state.map.endDate;
    filteredRows = allRows.filter(r => {
      if (!r.order_date) return false;
      const d = r.order_date.substring(0, 10);
      return d >= s && d <= e;
    });
    dateContextLabel = `${s} &ndash; ${e}`;
  }

  // 6. Zero Data / Empty State
  if (filteredRows.length === 0) {
    container.innerHTML = `
      ${headerHtml}
      ${dateHtml}
      <div class="loc-date-context-badge"><i class="fa-regular fa-clock"></i> ${dateContextLabel}</div>
      <div class="loc-alert info" style="margin-bottom:12px;">
        <i class="fa-solid fa-circle-info"></i>
        <span>No transactions found for <strong>${esc(country)}</strong> in this period.</span>
      </div>
      <div class="loc-kpi-grid">
        <div class="loc-kpi-item"><div class="loc-kpi-label">Sales</div><div class="loc-kpi-val">$0.00</div><div class="loc-kpi-sub">0 line items</div></div>
        <div class="loc-kpi-item"><div class="loc-kpi-label">Profit</div><div class="loc-kpi-val">$0.00</div><div class="loc-kpi-sub">Margin: 0.0%</div></div>
        <div class="loc-kpi-item"><div class="loc-kpi-label">Orders</div><div class="loc-kpi-val">0</div><div class="loc-kpi-sub">0 distinct orders</div></div>
        <div class="loc-kpi-item"><div class="loc-kpi-label">Shipping Cost</div><div class="loc-kpi-val">$0.00</div><div class="loc-kpi-sub">0.0% of sales</div></div>
      </div>
      <div style="text-align:center;margin-top:10px;">
        <button class="loc-quick-btn" onclick="setLocDatePreset('all')"><i class="fa-solid fa-rotate-left"></i> Reset to All-Time</button>
      </div>
      <div class="loc-coverage-note" style="margin-top:auto;">
        <span>Coverage: 0 matching records (${fmtNum(allRows.length)} total records loaded)</span>
        <span class="badge badge-muted">Zero Data</span>
      </div>
    `;
    return;
  }

  // 7. Reconcile Metrics
  const totalSales = filteredRows.reduce((sum, r) => sum + (Number(r.sales) || 0), 0);
  const totalProfit = filteredRows.reduce((sum, r) => sum + (Number(r.profit) || 0), 0);
  const totalShipping = filteredRows.reduce((sum, r) => sum + (Number(r.shipping_cost) || 0), 0);
  const totalQuantity = filteredRows.reduce((sum, r) => sum + (Number(r.quantity) || 0), 0);

  const uniqueOrdersSet = new Set(filteredRows.map(r => r.order_id_raw || r.order_key || r.row_id));
  const uniqueOrdersCount = uniqueOrdersSet.size;
  const lineItemsCount = filteredRows.length;

  const profitMargin = totalSales > 0 ? (totalProfit / totalSales) * 100 : 0;
  const avgShippingPerOrder = uniqueOrdersCount > 0 ? totalShipping / uniqueOrdersCount : 0;
  const shippingSalesRatio = totalSales > 0 ? (totalShipping / totalSales) * 100 : 0;

  // Ship-Mode Breakdown (reconciled by unique order_id_raw)
  const shipModes = [
    { key: 'Standard Class', color: '#4f8ef7', badge: 'badge-muted' },
    { key: 'Second Class',   color: '#06b6d4', badge: 'badge-info' },
    { key: 'First Class',    color: '#f59e0b', badge: 'badge-warning' },
    { key: 'Same Day',       color: '#ec4899', badge: 'badge-danger' },
  ];

  const orderShipMap = new Map();
  const shipModeData = {
    'Standard Class': { orders: 0, sales: 0, shipping: 0 },
    'Second Class':   { orders: 0, sales: 0, shipping: 0 },
    'First Class':    { orders: 0, sales: 0, shipping: 0 },
    'Same Day':       { orders: 0, sales: 0, shipping: 0 },
  };

  filteredRows.forEach(r => {
    const id = r.order_id_raw || r.order_key || r.row_id;
    const sm = r.ship_mode || 'Standard Class';
    if (!orderShipMap.has(id)) {
      orderShipMap.set(id, sm);
    }
    if (shipModeData[sm]) {
      shipModeData[sm].sales += (Number(r.sales) || 0);
      shipModeData[sm].shipping += (Number(r.shipping_cost) || 0);
    }
  });

  orderShipMap.forEach(sm => {
    if (shipModeData[sm]) shipModeData[sm].orders++;
  });

  const profitClass = totalProfit >= 0 ? 'color:var(--accent-green);' : 'color:var(--accent-red);';
  const profitSign = totalProfit >= 0 ? '+' : '';

  container.innerHTML = `
    ${headerHtml}
    ${dateHtml}

    <div class="loc-date-context-badge">
      <i class="fa-regular fa-clock"></i> ${dateContextLabel}
    </div>

    <!-- Mini KPI Grid -->
    <div class="loc-kpi-grid">
      <div class="loc-kpi-item">
        <div class="loc-kpi-label">Sales</div>
        <div class="loc-kpi-val">${fmt(totalSales)}</div>
        <div class="loc-kpi-sub">${fmtNum(lineItemsCount)} items &middot; ${fmtNum(totalQuantity)} units</div>
      </div>
      <div class="loc-kpi-item">
        <div class="loc-kpi-label">Net Profit</div>
        <div class="loc-kpi-val" style="${profitClass}">${profitSign}${fmt(totalProfit)}</div>
        <div class="loc-kpi-sub">Margin: ${profitMargin.toFixed(1)}%</div>
      </div>
      <div class="loc-kpi-item">
        <div class="loc-kpi-label">Order Volume</div>
        <div class="loc-kpi-val">${fmtNum(uniqueOrdersCount)}</div>
        <div class="loc-kpi-sub">Distinct order transactions</div>
      </div>
      <div class="loc-kpi-item">
        <div class="loc-kpi-label">Shipping Cost</div>
        <div class="loc-kpi-val">${fmt(totalShipping)}</div>
        <div class="loc-kpi-sub">Avg ${fmt(avgShippingPerOrder)}/order (${shippingSalesRatio.toFixed(1)}% of sales)</div>
      </div>
    </div>

    <!-- Ship Mode Breakdown -->
    <div class="loc-shipmode-wrap">
      <div class="loc-section-title">
        <span><i class="fa-solid fa-truck-fast" style="color:var(--accent-blue);margin-right:6px;"></i> Ship Mode Breakdown</span>
        <span style="font-size:11px;font-weight:400;color:var(--text-secondary);">${fmtNum(uniqueOrdersCount)} orders</span>
      </div>
      ${shipModes.map(sm => {
        const stats = shipModeData[sm.key] || { orders: 0, sales: 0, shipping: 0 };
        const pct = uniqueOrdersCount > 0 ? (stats.orders / uniqueOrdersCount) * 100 : 0;
        return `
          <div class="loc-shipmode-row">
            <div class="loc-shipmode-header">
              <span class="loc-shipmode-name">
                <span class="stat-row-dot" style="background:${sm.color};"></span>
                ${sm.key}
              </span>
              <span class="loc-shipmode-metrics">
                <strong>${fmtNum(stats.orders)} orders</strong> (${pct.toFixed(1)}%) &middot; ${fmt(stats.shipping)} ship
              </span>
            </div>
            <div class="loc-shipmode-track">
              <div class="loc-shipmode-bar" style="width:${pct}%;background:${sm.color};"></div>
            </div>
          </div>
        `;
      }).join('')}
    </div>

    <!-- Data Coverage Note -->
    <div class="loc-coverage-note">
      <span><i class="fa-solid fa-circle-check" style="color:var(--accent-green);margin-right:4px;"></i> Reconciled from ${fmtNum(lineItemsCount)} line items (${fmtNum(allRows.length)} loaded)</span>
      <span class="badge badge-success">Complete Data</span>
    </div>
  `;
}

